                if [ "${dispatch_shard_indices[$i]}" -gt 0 ] \
                   && [ "${dispatch_shard_indices[$i]}" -ne "$requirements_early_fail_shard" ] \
                   && kill -0 "${pids[$i]}" 2>/dev/null; then
